    // --- EVENTOS DE INTERFAZ ---
    private void UniversalSlot_MouseDown(object sender, MouseEventArgs e) { if (e.Button == MouseButtons.Left) { dragStartPos = e.Location; dragSlotIndex = (int)((PictureBox)sender).Tag; isDragging = false; } }
    private void UniversalSlot_MouseMove(object sender, MouseEventArgs e) { if (e.Button == MouseButtons.Left && dragSlotIndex != -1 && !isDragging) { if (Math.Abs(e.X - dragStartPos.X) > 4 || Math.Abs(e.Y - dragStartPos.Y) > 4) { PictureBox pb = (PictureBox)sender; bool isPartySlot = pb.Parent == tabParty; if (isPartySlot) { if (currentSaveData != null && dragSlotIndex < currentSaveData.Party.Count) { isDragging = true; int slot = dragSlotIndex; dragSlotIndex = -1; pb.DoDragDrop(new DragData { IsParty = true, BoxIndex = 0, SlotIndex = slot }, DragDropEffects.Move); } } else { if (currentSaveData != null && currentSaveData.Boxes[currentBoxIndex].Slots[dragSlotIndex] != null) { isDragging = true; int slot = dragSlotIndex; dragSlotIndex = -1; pb.DoDragDrop(new DragData { IsParty = false, BoxIndex = currentBoxIndex, SlotIndex = slot }, DragDropEffects.Move); } } } } }
    private void UniversalSlot_MouseUp(object sender, MouseEventArgs e) { if (!isDragging && dragSlotIndex != -1) { PictureBox pb = (PictureBox)sender; if (pb.Parent == tabParty) PartySlot_ClickAction(sender, EventArgs.Empty); else PcSlot_ClickAction(sender, EventArgs.Empty); } dragSlotIndex = -1; isDragging = false; }
    private void UniversalSlot_DragEnter(object sender, DragEventArgs e) { if (e.Data.GetDataPresent(typeof(DragData))) e.Effect = DragDropEffects.Move; }
    private void PartySlot_ClickAction(object sender, EventArgs e) { if (isUpdatingUI) return; PictureBox clickedSlot = sender as PictureBox; if (clickedSlot == null) return; int slotIndex = (int)clickedSlot.Tag; if (currentSaveData == null || slotIndex >= currentSaveData.Party.Count) { ApplyCurrentEdits(); grpEditor.Enabled = false; currentSlotIndex = -1; return; } ApplyCurrentEdits(); isEditingParty = true; currentSlotIndex = slotIndex; LoadPokemonToEditor(); }
    private void PcSlot_ClickAction(object sender, EventArgs e) { if (isUpdatingUI) return; PictureBox clickedSlot = sender as PictureBox; if (clickedSlot == null) return; int slotIndex = (int)clickedSlot.Tag; if (currentSaveData.Boxes[currentBoxIndex].Slots[slotIndex] == null) { ApplyCurrentEdits(); grpEditor.Enabled = false; currentSlotIndex = -1; return; } ApplyCurrentEdits(); isEditingParty = false; currentSlotIndex = slotIndex; LoadPokemonToEditor(); }
    private void PartySlot_DragDrop(object sender, DragEventArgs e) { DragData source = (DragData)e.Data.GetData(typeof(DragData)); PictureBox pb = sender as PictureBox; int targetSlot = (int)pb.Tag; Unified_DragDrop(source, true, 0, targetSlot); }
    private void PcSlot_DragDrop(object sender, DragEventArgs e) { DragData source = (DragData)e.Data.GetData(typeof(DragData)); PictureBox pb = sender as PictureBox; int targetSlot = (int)pb.Tag; Unified_DragDrop(source, false, currentBoxIndex, targetSlot); }
    private void Unified_DragDrop(DragData source, bool targetIsParty, int targetBox, int targetSlot) {
        if (source.IsParty == targetIsParty && source.BoxIndex == targetBox && source.SlotIndex == targetSlot) return; lblStatus.Text = "⏳ Moviendo Pokémon..."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents();
        try {
            ApplyCurrentEdits(); SaveWriter writer = new SaveWriter(currentSavePath, currentSaveData.RootData);
            if (source.IsParty && !targetIsParty) { if (currentSaveData.Boxes[targetBox].Slots[targetSlot] != null) { writer.SwapPokemonInRuby(true, 0, source.SlotIndex, false, targetBox, targetSlot); } else { writer.ClonePokemonInRuby(true, 0, source.SlotIndex, false, targetBox, targetSlot); writer.DeletePokemonInRuby(true, 0, source.SlotIndex); } } else if (!source.IsParty && targetIsParty) { if (targetSlot < currentSaveData.Party.Count) { writer.SwapPokemonInRuby(false, source.BoxIndex, source.SlotIndex, true, 0, targetSlot); } else { if (currentSaveData.Party.Count >= 6) { MessageBox.Show("El equipo ya está lleno.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } writer.ClonePokemonInRuby(false, source.BoxIndex, source.SlotIndex, true, 0, currentSaveData.Party.Count); writer.DeletePokemonInRuby(false, source.BoxIndex, source.SlotIndex); } } else if (!source.IsParty && !targetIsParty) { writer.SwapPokemonInRuby(false, source.BoxIndex, source.SlotIndex, false, targetBox, targetSlot); } else if (source.IsParty && targetIsParty) { if (targetSlot < currentSaveData.Party.Count) { writer.SwapPokemonInRuby(true, 0, source.SlotIndex, true, 0, targetSlot); } else { writer.ClonePokemonInRuby(true, 0, source.SlotIndex, true, 0, currentSaveData.Party.Count); writer.DeletePokemonInRuby(true, 0, source.SlotIndex); } }
            ReloadFromMemory(); if (isEditingParty == targetIsParty) { if (currentBoxIndex == targetBox || targetIsParty) { currentSlotIndex = targetIsParty ? Math.Min(targetSlot, currentSaveData.Party.Count - 1) : targetSlot; } } LoadPokemonToEditor(); lblStatus.Text = "Pokémon movido con éxito."; lblStatus.ForeColor = Color.Green;
        } finally { this.Cursor = Cursors.Default; }
    }
    private void MovePokemonQuick_Click(object sender, EventArgs e) { var pb = ((sender as ToolStripItem).Owner as ContextMenuStrip).SourceControl as PictureBox; if (pb == null) return; bool isParty = pb.Parent == tabParty; int slot = (int)pb.Tag; if (isParty) { int targetBox = -1, targetSlot = -1; for (int b = 0; b < currentSaveData.Boxes.Count; b++) { for (int s = 0; s < 30; s++) { if (currentSaveData.Boxes[b].Slots[s] == null) { targetBox = b; targetSlot = s; break; } } if (targetBox != -1) break; } if (targetBox == -1) { MessageBox.Show("Todas las cajas del PC están llenas.", "Aviso"); return; } Unified_DragDrop(new DragData { IsParty = true, BoxIndex = 0, SlotIndex = slot }, false, targetBox, targetSlot); } else { if (currentSaveData.Party.Count >= 6) { MessageBox.Show("El equipo ya está lleno.", "Aviso"); return; } Unified_DragDrop(new DragData { IsParty = false, BoxIndex = currentBoxIndex, SlotIndex = slot }, true, 0, currentSaveData.Party.Count); } }
    private void DeletePokemon_Click(object sender, EventArgs e) { var pb = ((sender as ToolStripItem).Owner as ContextMenuStrip).SourceControl as PictureBox; if (pb == null) return; bool isParty = pb.Parent == tabParty; int slot = (int)pb.Tag; if (MessageBox.Show("¿Eliminar de forma permanente?", "Confirmar", MessageBoxButtons.YesNo, MessageBoxIcon.Warning) == DialogResult.Yes) { lblStatus.Text = "⏳ Eliminando Pokémon..."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents(); try { ApplyCurrentEdits(); SyncAllToRuby(); SaveWriter writer = new SaveWriter(currentSavePath, currentSaveData.RootData); if (isParty) writer.DeletePokemonInRuby(true, 0, slot); else writer.DeletePokemonInRuby(false, currentBoxIndex, slot); ReloadFromMemory(); grpEditor.Enabled = false; lblStatus.Text = "Pokémon eliminado."; lblStatus.ForeColor = Color.Red; } finally { this.Cursor = Cursors.Default; } } }
    private void BtnAddPokemon_Click(object sender, EventArgs e) { if (currentSaveData == null) return; int targetSlot = -1; for (int i = 0; i < 30; i++) { if (currentSaveData.Boxes[currentBoxIndex].Slots[i] == null) { targetSlot = i; break; } } if (targetSlot == -1) { MessageBox.Show("La caja actual está llena.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning); return; } using (AddPokemonForm form = new AddPokemonForm(pbs)) { if (form.ShowDialog() == DialogResult.OK) { lblStatus.Text = "⏳ Generando Pokémon e inyectando en la caja..."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents(); try { ApplyCurrentEdits(); SyncAllToRuby(); SaveWriter writer = new SaveWriter(currentSavePath, currentSaveData.RootData); string intSpc = form.SelectedSpeciesInternal; string gr = pbs.SpeciesGrowthRates.ContainsKey(intSpc) ? pbs.SpeciesGrowthRates[intSpc] : "MEDIUMFAST"; int exactExp = PokemonUtils.CalculateExp(form.Level, gr); bool success = writer.AddPokemon(false, currentBoxIndex, intSpc, form.SelectedSpeciesName, form.Level, exactExp, "AUTO_0"); if (success) { ReloadFromMemory(); isEditingParty = false; currentSlotIndex = targetSlot; LoadPokemonToEditor(); lblStatus.Text = $"¡Pokémon añadido! Habilidad lista para el Modo Random."; lblStatus.ForeColor = Color.Green; } } finally { this.Cursor = Cursors.Default; } } } }
    private void BtnBoxChange_DragOver(object sender, DragEventArgs e) { if (e.Data.GetDataPresent(typeof(DragData)) && (DateTime.Now - lastBoxSwitch).TotalMilliseconds > 700) { Button btn = sender as Button; if (btn == btnNextBox && cbBoxSelector.SelectedIndex < cbBoxSelector.Items.Count - 1) cbBoxSelector.SelectedIndex++; else if (btn == btnPrevBox && cbBoxSelector.SelectedIndex > 0) cbBoxSelector.SelectedIndex--; lastBoxSwitch = DateTime.Now; } }

    private void UpdateBagItemDropdown() { if (!pbs.IsLoaded || tabBagPockets.SelectedIndex < 0) return; int currentPocket = tabBagPockets.SelectedIndex + 1; if (dgvPockets[currentPocket] == null) return; string currentSelection = cbBagItems.Text; cbBagItems.Items.Clear(); HashSet<string> existingItems = new HashSet<string>(StringComparer.OrdinalIgnoreCase); if (currentPocket == 4 || currentPocket == 8) { foreach (DataGridViewRow row in dgvPockets[currentPocket].Rows) { if (row.Cells[0].Value != null) existingItems.Add(row.Cells[0].Value.ToString()); } } foreach (var kvp in pbs.Items) { int pkt = pbs.ItemPockets.ContainsKey(kvp.Key) ? pbs.ItemPockets[kvp.Key] : 1; if (pkt == currentPocket && !existingItems.Contains(kvp.Key)) { cbBagItems.Items.Add(pbs.GetName(pbs.Items, kvp.Key, kvp.Value)); } } if (cbBagItems.Items.Contains(currentSelection)) cbBagItems.SelectedItem = currentSelection; else if (cbBagItems.Items.Count > 0) cbBagItems.SelectedIndex = 0; }
    private void BtnBagAdd_Click(object sender, EventArgs e) { if (string.IsNullOrWhiteSpace(cbBagItems.Text)) return; string intId = PokemonUtils.GetInternalId(pbs.Items, cbBagItems.Text, "", pbs); if (string.IsNullOrEmpty(intId)) return; int pocket = tabBagPockets.SelectedIndex + 1; int qtyToAdd = (pocket == 4 || pocket == 8) ? 1 : (int)numBagQty.Value; foreach (DataGridViewRow row in dgvPockets[pocket].Rows) { if (qtyToAdd <= 0) break; if (row.Cells[0].Value != null && row.Cells[0].Value.ToString().Equals(intId, StringComparison.OrdinalIgnoreCase)) { int currentQty = Convert.ToInt32(row.Cells[2].Value); int maxAllowed = (pocket == 4 || pocket == 8) ? 1 : 999; if (currentQty < maxAllowed) { int spaceAvailable = maxAllowed - currentQty; int amountToFill = Math.Min(qtyToAdd, spaceAvailable); row.Cells[2].Value = currentQty + amountToFill; qtyToAdd -= amountToFill; } else if (pocket == 4 || pocket == 8) { qtyToAdd = 0; } } } while (qtyToAdd > 0) { int maxAllowed = (pocket == 4 || pocket == 8) ? 1 : 999; int amountForNewSlot = Math.Min(qtyToAdd, maxAllowed); dgvPockets[pocket].Rows.Add(intId, cbBagItems.Text, amountForNewSlot); qtyToAdd -= amountForNewSlot; if (pocket == 4 || pocket == 8) break; } UpdateBagItemDropdown(); }
    private void BtnBagMaxSelected_Click(object sender, EventArgs e) { if (tabBagPockets.SelectedIndex < 0) return; int pocket = tabBagPockets.SelectedIndex + 1; if (pocket == 4 || pocket == 8) { MessageBox.Show("Las MTs y Objetos Clave no pueden tener más de 1 unidad.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Information); return; } if (dgvPockets[pocket].SelectedRows.Count > 0) { foreach (DataGridViewRow row in dgvPockets[pocket].SelectedRows) { if (!row.IsNewRow) row.Cells[2].Value = 999; } UpdateBagItemDropdown(); } else { MessageBox.Show("Selecciona un objeto de la tabla haciendo clic en su fila.", "Aviso", MessageBoxButtons.OK, MessageBoxIcon.Warning); } }
    private void BtnBagMaxCurrent_Click(object sender, EventArgs e) { if (currentSaveData == null) return; lblStatus.Text = "⏳ Maximizando los objetos que ya tienes..."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents(); try { for (int pId = 1; pId <= 8; pId++) { if (dgvPockets[pId] == null) continue; int targetQty = (pId == 4 || pId == 8) ? 1 : 999; foreach (DataGridViewRow row in dgvPockets[pId].Rows) { if (row.Cells[0].Value != null) row.Cells[2].Value = targetQty; } } UpdateBagItemDropdown(); lblStatus.Text = "¡Tus objetos actuales han sido maximizados a 999!"; lblStatus.ForeColor = Color.Green; } finally { this.Cursor = Cursors.Default; } }
    private void BtnBagAddAll_Click(object sender, EventArgs e) { if (!pbs.IsLoaded) return; lblStatus.Text = "⏳ Inyectando todos los objetos del juego... Esto puede tardar unos segundos."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents(); try { foreach (var kvp in pbs.Items) { string intId = kvp.Key; string realName = pbs.GetName(pbs.Items, intId, kvp.Value); int pkt = pbs.ItemPockets.ContainsKey(intId) ? pbs.ItemPockets[intId] : 1; int targetQty = (pkt == 4 || pkt == 8) ? 1 : 999; bool found = false; foreach (DataGridViewRow row in dgvPockets[pkt].Rows) { if (row.Cells[0].Value != null && row.Cells[0].Value.ToString().Equals(intId, StringComparison.OrdinalIgnoreCase)) { found = true; if (pkt != 4 && pkt != 8) row.Cells[2].Value = targetQty; break; } } if (!found) dgvPockets[pkt].Rows.Add(intId, realName, targetQty); } UpdateBagItemDropdown(); lblStatus.Text = "¡Todos los objetos del juego han sido añadidos a tu mochila!"; lblStatus.ForeColor = Color.Green; } finally { this.Cursor = Cursors.Default; } }
    private void BtnBagRemove_Click(object sender, EventArgs e) { if (tabBagPockets.SelectedIndex < 0) return; int pocket = tabBagPockets.SelectedIndex + 1; if (dgvPockets[pocket].SelectedRows.Count > 0) { foreach (DataGridViewRow row in dgvPockets[pocket].SelectedRows) { if (!row.IsNewRow) dgvPockets[pocket].Rows.Remove(row); } UpdateBagItemDropdown(); } else { MessageBox.Show("Por favor, selecciona primero una fila en la tabla de arriba para borrarla.", "Borrar Objeto", MessageBoxButtons.OK, MessageBoxIcon.Information); } }

    private void ChkShiny_CheckedChanged(object sender, EventArgs e) { if (isUpdatingUI) return; chkShiny.BackColor = chkShiny.Checked ? Color.Gold : SystemColors.Control; if (chkShiny.Checked && chkSuperShiny.Checked) { isUpdatingUI = true; chkSuperShiny.Checked = false; chkSuperShiny.BackColor = SystemColors.Control; isUpdatingUI = false; } ApplyCurrentEdits(); LoadSpriteOnly(); }
    private void ChkSuperShiny_CheckedChanged(object sender, EventArgs e) { if (isUpdatingUI) return; chkSuperShiny.BackColor = chkSuperShiny.Checked ? Color.Plum : SystemColors.Control; if (chkSuperShiny.Checked && chkShiny.Checked) { isUpdatingUI = true; chkShiny.Checked = false; chkShiny.BackColor = SystemColors.Control; isUpdatingUI = false; } ApplyCurrentEdits(); LoadSpriteOnly(); }
