    private void BtnDescMoves_Click(int idx) { string internalId = PokemonUtils.GetInternalId(pbs.Moves, cbMoves[idx].Text, "", pbs); string desc = pbs.MoveDescriptions.TryGetValue(internalId, out string d) ? d : "Sin descripción disponible."; MessageBox.Show(desc, $"Movimiento: {cbMoves[idx].Text}", MessageBoxButtons.OK, MessageBoxIcon.Information); }
    private void BtnMaxPP_Click(object sender, EventArgs e) { for (int i = 0; i < 4; i++) { if (cbMoves[i].Enabled && !string.IsNullOrWhiteSpace(cbMoves[i].Text)) { numPPUps[i].Value = 3; numPPs[i].Value = numPPs[i].Maximum; } } }
    private void BtnInfo_Click(object sender, EventArgs e) { ApplyCurrentEdits(); Pokemon p = GetCurrentPokemon(); if (p == null) return; InfoForm infoWindow = new InfoForm(p, picSprite.Image, pbs); infoWindow.ShowDialog(); }
    private void ChangeForm_Click(object sender, EventArgs e) { var pb = ((sender as ToolStripItem).Owner as ContextMenuStrip)?.SourceControl as PictureBox; if (pb == null && sender is Button) pb = partySlots[currentSlotIndex]; if (pb == null) return; bool isParty = pb.Parent == tabParty || (sender is Button && isEditingParty); int slot = (sender is Button) ? currentSlotIndex : (int)pb.Tag; if (currentSaveData == null) return; Pokemon p = isParty ? (slot < currentSaveData.Party.Count ? currentSaveData.Party[slot] : null) : currentSaveData.Boxes[currentBoxIndex].Slots[slot]; if (p == null) return; using (ChangeFormDialog formDialog = new ChangeFormDialog(pbs, p)) { if (formDialog.ShowDialog() == DialogResult.OK) { lblStatus.Text = "⏳ Aplicando transformación y guardando..."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents(); try { ApplyCurrentEdits(); p.Form = formDialog.SelectedForm; if (!string.IsNullOrEmpty(formDialog.SelectedSpeciesInternal)) { p.InternalSpecies = formDialog.SelectedSpeciesInternal; p.Species = pbs.GetName(pbs.Species, p.InternalSpecies, p.InternalSpecies); } p.InternalAbility = "AUTO_0"; p.Ability = "Auto: Ranura 1"; p.Nickname = p.Species; SyncAllToRuby(); ReloadFromMemory(); lblStatus.Text = $"Forma de {p.Nickname} actualizada correctamente."; lblStatus.ForeColor = Color.DarkViolet; } finally { this.Cursor = Cursors.Default; } } } }

    private void RefreshPartyGrid() { if (currentSaveData == null) return; for (int i = 0; i < 6; i++) { if (partySlots[i].Image != null) partySlots[i].Image.Dispose(); partySlots[i].Image = null; if (i < currentSaveData.Party.Count) { Pokemon p = currentSaveData.Party[i]; partySlots[i].BackColor = Color.LightCyan; partySlots[i].Image = SpriteManager.GetPokemonIcon(AppRoot, p.InternalSpecies, p.Form, p.IsShiny || p.IsSuperShiny); partyLabels[i].Text = $"{p.Nickname}\nNv. {p.Level}"; partyLabels[i].ForeColor = Color.Black; } else { partySlots[i].BackColor = Color.WhiteSmoke; partyLabels[i].Text = "Vacío"; partyLabels[i].ForeColor = Color.Gray; } } }
    private void RefreshPCGrid() { if (currentSaveData == null || currentBoxIndex < 0 || currentBoxIndex >= currentSaveData.Boxes.Count) return; var box = currentSaveData.Boxes[currentBoxIndex]; for (int i = 0; i < 30; i++) { Pokemon p = box.Slots[i]; if (pcSlots[i].Image != null) pcSlots[i].Image.Dispose(); pcSlots[i].Image = null; pcSlots[i].BackColor = (p != null) ? Color.LightCyan : Color.WhiteSmoke; if (p != null) pcSlots[i].Image = SpriteManager.GetPokemonIcon(AppRoot, p.InternalSpecies, p.Form, p.IsShiny || p.IsSuperShiny); } }
    private void UpdateStatColorsByNature() { string selectedText = cbNature.Text; string intNat = PokemonUtils.GetInternalIdFromNatureText(selectedText, pbs); for (int i = 0; i < 6; i++) lblStatNames[i].ForeColor = Color.Black; switch (intNat?.ToUpper()) { case "LONELY": lblStatNames[1].ForeColor = Color.Red; lblStatNames[2].ForeColor = Color.Blue; break; case "BRAVE":  lblStatNames[1].ForeColor = Color.Red; lblStatNames[5].ForeColor = Color.Blue; break; case "ADAMANT":lblStatNames[1].ForeColor = Color.Red; lblStatNames[3].ForeColor = Color.Blue; break; case "NAUGHTY":lblStatNames[1].ForeColor = Color.Red; lblStatNames[4].ForeColor = Color.Blue; break; case "BOLD":   lblStatNames[2].ForeColor = Color.Red; lblStatNames[1].ForeColor = Color.Blue; break; case "RELAXED":lblStatNames[2].ForeColor = Color.Red; lblStatNames[5].ForeColor = Color.Blue; break; case "IMPISH": lblStatNames[2].ForeColor = Color.Red; lblStatNames[3].ForeColor = Color.Blue; break; case "LAX":    lblStatNames[2].ForeColor = Color.Red; lblStatNames[4].ForeColor = Color.Blue; break; case "MODEST": lblStatNames[3].ForeColor = Color.Red; lblStatNames[1].ForeColor = Color.Blue; break; case "MILD":   lblStatNames[3].ForeColor = Color.Red; lblStatNames[2].ForeColor = Color.Blue; break; case "QUIET":  lblStatNames[3].ForeColor = Color.Red; lblStatNames[5].ForeColor = Color.Blue; break; case "RASH":   lblStatNames[3].ForeColor = Color.Red; lblStatNames[4].ForeColor = Color.Blue; break; case "CALM":   lblStatNames[4].ForeColor = Color.Red; lblStatNames[1].ForeColor = Color.Blue; break; case "GENTLE": lblStatNames[4].ForeColor = Color.Red; lblStatNames[2].ForeColor = Color.Blue; break; case "SASSY":  lblStatNames[4].ForeColor = Color.Red; lblStatNames[5].ForeColor = Color.Blue; break; case "CAREFUL":lblStatNames[4].ForeColor = Color.Red; lblStatNames[3].ForeColor = Color.Blue; break; case "TIMID":  lblStatNames[5].ForeColor = Color.Red; lblStatNames[1].ForeColor = Color.Blue; break; case "HASTY":  lblStatNames[5].ForeColor = Color.Red; lblStatNames[2].ForeColor = Color.Blue; break; case "JOLLY":  lblStatNames[5].ForeColor = Color.Red; lblStatNames[3].ForeColor = Color.Blue; break; case "NAIVE":  lblStatNames[5].ForeColor = Color.Red; lblStatNames[4].ForeColor = Color.Blue; break; } }
    private void UpdatePPLimits(int moveIndex) { string moveName = cbMoves[moveIndex].Text; string internalId = PokemonUtils.GetInternalId(pbs.Moves, moveName, "", pbs); int basePP = 10; if (pbs.MovePPs.TryGetValue(internalId, out int pp)) basePP = pp; int ppUps = (int)numPPUps[moveIndex].Value; int maxPP = basePP + (basePP * ppUps / 5); numPPs[moveIndex].Maximum = Math.Max(1, maxPP); if (numPPs[moveIndex].Value > numPPs[moveIndex].Maximum) numPPs[moveIndex].Value = numPPs[moveIndex].Maximum; }

    private void ApplyCurrentEdits() {
        if (isUpdatingUI) return; Pokemon p = GetCurrentPokemon(); if (p == null) return;
        try {
            isUpdatingUI = true; p.Nickname = txtNickname.Text; p.Level = (int)numLevel.Value; string gr = pbs.SpeciesGrowthRates.ContainsKey(p.InternalSpecies) ? pbs.SpeciesGrowthRates[p.InternalSpecies] : "MEDIUMFAST"; p.Exp = PokemonUtils.CalculateExp(p.Level, gr); p.IsShiny = chkShiny.Checked; p.IsSuperShiny = chkSuperShiny.Checked; p.Gender = cbGender.Text; p.HeldItem = cbItem.Text; p.InternalHeldItem = PokemonUtils.GetInternalId(pbs.Items, cbItem.Text, p.InternalHeldItem, pbs); if (string.IsNullOrWhiteSpace(p.InternalHeldItem)) p.InternalHeldItem = "Ninguno"; p.Nature = PokemonUtils.GetInternalIdFromNatureText(cbNature.Text, pbs); p.InternalNature = PokemonUtils.GetInternalIdFromNatureText(cbNature.Text, pbs); if (cbAbility.Text == "Auto: Ranura 1") { p.Ability = "Auto: Ranura 1"; p.InternalAbility = "AUTO_0"; } else if (cbAbility.Text == "Auto: Ranura 2") { p.Ability = "Auto: Ranura 2"; p.InternalAbility = "AUTO_1"; } else if (cbAbility.Text == "Auto: Oculta") { p.Ability = "Auto: Oculta"; p.InternalAbility = "AUTO_2"; } else { p.Ability = cbAbility.Text; p.InternalAbility = PokemonUtils.GetInternalId(pbs.Abilities, cbAbility.Text, p.InternalAbility, pbs); } for (int i = 0; i < 6; i++) { p.IVs[i] = (int)numIVs[i].Value; p.EVs[i] = (int)numEVs[i].Value; } p.Moves.Clear(); for (int i = 0; i < 4; i++) { if (!string.IsNullOrWhiteSpace(cbMoves[i].Text)) { p.Moves.Add(new PokemonMove { Name = cbMoves[i].Text, InternalName = PokemonUtils.GetInternalId(pbs.Moves, cbMoves[i].Text, "", pbs), PP = (int)numPPs[i].Value, PPUp = (int)numPPUps[i].Value }); } }
            if (isEditingParty) RefreshPartyGrid(); else RefreshPCGrid();
        } catch (Exception ex) { LogError(ex, "ApplyCurrentEdits"); } finally { isUpdatingUI = false; }
    }

    private void BtnLoad_Click(object sender, EventArgs e) { string appDataRoaming = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData); string[] possibleFolders = { Path.Combine(appDataRoaming, "Pokemon Anil"), Path.Combine(appDataRoaming, "Pokémon Añil"), Path.Combine(appDataRoaming, "PokemonAnil") }; string initialDir = possibleFolders.FirstOrDefault(Directory.Exists) ?? appDataRoaming; using (OpenFileDialog ofd = new OpenFileDialog { Title = "Seleccionar Partida (.rxdata)", Filter = "Partidas (*.rxdata)|*.rxdata|Todos (*.*)|*.*", InitialDirectory = initialDir, RestoreDirectory = true }) { if (ofd.ShowDialog() == DialogResult.OK) { currentSavePath = ofd.FileName; LoadSaveFile(); } } }

    private void LoadSaveFile() {
        lblStatus.Text = "⏳ Cargando partida y leyendo base de datos... ¡Un momento!"; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents();
        try {
            SaveParser parser = new SaveParser(currentSavePath, pbs); currentSaveData = parser.ParseSave(); isUpdatingUI = true; 
            cbBoxSelector.Items.Clear(); foreach (var box in currentSaveData.Boxes) cbBoxSelector.Items.Add($"{box.Name} (Caja {box.BoxIndex})"); 
            foreach (var grid in dgvPockets) grid?.Rows.Clear(); 
            foreach (var item in currentSaveData.Bag) { int pId = item.Pocket >= 1 && item.Pocket <= 8 ? item.Pocket : 1; string realName = pbs != null ? pbs.GetName(pbs.Items, item.InternalName, item.Name) : item.Name; dgvPockets[pId]?.Rows.Add(item.InternalName, realName, item.Quantity); }
            
            SaveWriter tempWriter = new SaveWriter(currentSavePath, currentSaveData.RootData);
            numMoney.Value = Math.Min(numMoney.Maximum, Math.Max(0m, (decimal)tempWriter.GetMoney()));

            if (pbs.IsLoaded) { cbNature.Items.Clear(); foreach (var natKvp in pbs.Natures) { string disp = PokemonUtils.GetNatureDisplayName(natKvp.Value, natKvp.Key); if (!cbNature.Items.Contains(disp)) cbNature.Items.Add(disp); } cbAbility.Items.Clear(); cbAbility.Items.AddRange(pbs.Abilities.Values.Distinct().ToArray()); cbItem.Items.Clear(); var allItemsList = pbs.Items.Select(x => pbs.GetName(pbs.Items, x.Key, x.Value)).Distinct().ToArray(); cbItem.Items.AddRange(allItemsList); var allMoves = pbs.Moves.Values.Distinct().ToArray(); foreach (var cb in cbMoves) { cb.Items.Clear(); cb.Items.AddRange(allMoves); } }
            isUpdatingUI = false; if (cbBoxSelector.Items.Count > 0) cbBoxSelector.SelectedIndex = 0; 
            RefreshPartyGrid(); RefreshPCGrid(); tabBagPockets.SelectedIndex = 0; UpdateBagItemDropdown();
            btnSave.Enabled = true; lblStatus.Text = $"Partida cargada: {Path.GetFileName(currentSavePath)}"; lblStatus.ForeColor = Color.Green;
        } catch (Exception ex) { lblStatus.Text = $"Error al cargar. Revisa errorlog.txt"; lblStatus.ForeColor = Color.Red; btnSave.Enabled = false; LogError(ex, "LoadSaveFile"); } finally { this.Cursor = Cursors.Default; }
    }

    private void CbBoxSelector_SelectedIndexChanged(object sender, EventArgs e) { if (isUpdatingUI || cbBoxSelector.SelectedIndex < 0 || currentSaveData == null) return; currentBoxIndex = cbBoxSelector.SelectedIndex; RefreshPCGrid(); }
    private Pokemon GetCurrentPokemon() { if (currentSaveData == null || currentSlotIndex < 0) return null; if (isEditingParty && currentSlotIndex < currentSaveData.Party.Count) return currentSaveData.Party[currentSlotIndex]; if (!isEditingParty && currentSlotIndex < 30) return currentSaveData.Boxes[currentBoxIndex].Slots[currentSlotIndex]; return null; }
    
    private void LoadPokemonToEditor() {
        Pokemon p = GetCurrentPokemon(); if (p == null) return; isUpdatingUI = true;
        btnChangeFormInEditor.Visible = FormDatabase.HasFormsOrParadox(p.InternalSpecies, AppRoot); txtNickname.Text = p.Nickname; numLevel.Value = Math.Min(100, Math.Max(1, p.Level)); chkShiny.Checked = p.IsShiny; chkSuperShiny.Checked = p.IsSuperShiny; chkShiny.BackColor = p.IsShiny ? Color.Gold : SystemColors.Control; chkSuperShiny.BackColor = p.IsSuperShiny ? Color.Plum : SystemColors.Control; if (cbGender.Items.Contains(p.Gender)) cbGender.SelectedItem = p.Gender; else cbGender.SelectedIndex = 0; string natDisp = PokemonUtils.GetNatureDisplayName(p.Nature, p.InternalNature); if (cbNature.Items.Contains(natDisp)) cbNature.SelectedItem = natDisp; else cbNature.Text = natDisp; UpdateStatColorsByNature(); string realItemName = pbs.GetName(pbs.Items, p.InternalHeldItem, p.HeldItem); if (cbItem.Items.Contains(realItemName)) cbItem.SelectedItem = realItemName; else cbItem.Text = realItemName; if (p.InternalAbility == "AUTO_0" || p.InternalAbility == "AUTO") { cbAbility.Text = "Auto: Ranura 1"; } else if (p.InternalAbility == "AUTO_1") { cbAbility.Text = "Auto: Ranura 2"; } else if (p.InternalAbility == "AUTO_2") { cbAbility.Text = "Auto: Oculta"; } else { if (cbAbility.Items.Contains(p.Ability)) cbAbility.SelectedItem = p.Ability; else cbAbility.Text = p.Ability; } for (int i = 0; i < 6; i++) { numIVs[i].Value = Math.Min(31, Math.Max(0, p.IVs[i])); numEVs[i].Value = Math.Min(252, Math.Max(0, p.EVs[i])); } for (int i = 0; i < 4; i++) { cbMoves[i].Enabled = numPPs[i].Enabled = numPPUps[i].Enabled = btnDescMoves[i].Enabled = true; if (i < p.Moves.Count) { if (cbMoves[i].Items.Contains(p.Moves[i].Name)) cbMoves[i].SelectedItem = p.Moves[i].Name; else cbMoves[i].Text = p.Moves[i].Name; numPPUps[i].Value = p.Moves[i].PPUp; int bp = 10; if (pbs.MovePPs.TryGetValue(PokemonUtils.GetInternalId(pbs.Moves, cbMoves[i].Text, "", pbs), out int pp)) bp = pp; int maxP = bp + (bp * (int)numPPUps[i].Value / 5); numPPs[i].Maximum = Math.Max(1, maxP); numPPs[i].Value = Math.Min(numPPs[i].Maximum, p.Moves[i].PP); } else { cbMoves[i].SelectedIndex = -1; cbMoves[i].Text = ""; numPPs[i].Value = numPPUps[i].Value = 0; } } isUpdatingUI = false; LoadSpriteOnly(); grpEditor.Enabled = true;
    }

    private void LoadSpriteOnly() { Pokemon p = GetCurrentPokemon(); if (p == null) return; if (picSprite.Image != null) picSprite.Image.Dispose(); picSprite.Image = SpriteManager.GetPokemonIcon(AppRoot, p.InternalSpecies, p.Form, chkShiny.Checked || chkSuperShiny.Checked); }

    private void BtnSave_Click(object sender, EventArgs e) {
        if (currentSaveData == null || string.IsNullOrEmpty(currentSavePath)) return;
        lblStatus.Text = "⏳ Inyectando cambios en la partida... No cierres la ventana."; lblStatus.ForeColor = Color.DarkOrange; this.Cursor = Cursors.WaitCursor; Application.DoEvents();
        try {
            ApplyCurrentEdits(); currentSaveData.Bag.Clear();
            for (int pId = 1; pId <= 8; pId++) { foreach (DataGridViewRow row in dgvPockets[pId].Rows) { if (row.Cells[0].Value != null) { currentSaveData.Bag.Add(new ItemSlot { InternalName = row.Cells[0].Value.ToString(), Name = row.Cells[1].Value.ToString(), Quantity = Convert.ToInt32(row.Cells[2].Value), Pocket = pId }); } } }
            SyncAllToRuby(); SaveWriter writer = new SaveWriter(currentSavePath, currentSaveData.RootData); writer.SyncBag(currentSaveData.Bag); writer.SyncMoney((long)numMoney.Value);
            if (writer.Save()) { lblStatus.Text = "¡Partida guardada correctamente! Se han inyectado todas las modificaciones."; lblStatus.ForeColor = Color.Blue; }
        } catch (Exception ex) { lblStatus.Text = $"Error crítico al guardar. Revisa errorlog.txt"; lblStatus.ForeColor = Color.Red; LogError(ex, "BtnSave_Click"); } finally { this.Cursor = Cursors.Default; }
    }

    private void SyncAllToRuby() { SaveWriter writer = new SaveWriter(currentSavePath, currentSaveData.RootData); for (int i = 0; i < currentSaveData.Party.Count; i++) writer.SyncPokemon(currentSaveData.Party[i], true, 0, i); foreach (var box in currentSaveData.Boxes) for (int i = 0; i < 30; i++) if (box.Slots[i] != null) writer.SyncPokemon(box.Slots[i], false, box.BoxIndex - 1, i); }
    private void ReloadFromMemory() { isUpdatingUI = true; SaveParser parser = new SaveParser(currentSavePath, pbs); currentSaveData = parser.ParseSave(currentSaveData.RootData); isUpdatingUI = false; RefreshPartyGrid(); RefreshPCGrid(); LoadPokemonToEditor(); }
    private void LogError(Exception ex, string context = "") { try { using (StreamWriter sw = new StreamWriter(Path.Combine(AppRoot, "errorlog.txt"), true)) sw.WriteLine($"[{DateTime.Now:yyyy-MM-dd HH:mm:ss}] ERROR: {context}\n{ex.ToString()}\n{new string('-', 50)}"); } catch { } }
}